import{_ as e,l as r,o as l,c as i,v as o,p,x as s,d as n,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"z-loss 与 logit 稳定","description":"","frontmatter":{"title":"z-loss 与 logit 稳定","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/z-loss.md","filePath":"llm/z-loss.md","lastUpdated":1789023840000}'),z={name:"llm/z-loss.md"};function d(E,a,_,g,c,u){const t=r("Mermaid");return l(),i("div",null,[a[1]||(a[1]=o('<h1 id="z-loss-与-logit-稳定" tabindex="-1">z-loss 与 logit 稳定 <a class="header-anchor" href="#z-loss-与-logit-稳定" aria-label="Permalink to &quot;z-loss 与 logit 稳定&quot;">​</a></h1><div class="epigraph"><p>当分类头的 log-sum-exp 无界增长，softmax 仍可给出合法概率，但半精度与路由器会先在这个尺度上溢出或锁死。</p><footer>—— PaLM、Gopher 一类大规模训练中的 logit 正则；MoE 上的 router z-loss 见 ST-MoE / Switch 稳定性讨论</footer></div><p><a href="/llm/weight-decay-mup">上一课</a> 管权重范数与宽度定标。本课管的是 <strong>logits 的绝对尺度</strong>。交叉熵只约束概率，不约束 \\(z=\\log\\sum_j e^{\\ell_j}\\)：把全部 logits 同时加一个大常数，\\(p\\) 不变，\\(z\\) 变。混合精度、<a href="/llm/cut-cross-entropy">Cut cross-entropy</a> 的片上归约、以及 MoE 路由 softmax，都会在 \\(z\\) 过大时先坏掉。z-loss 给 \\(z^2\\) 一个小系数，把尺度钉住。后课的 NaN skip 假定你已经知道哪些尖峰来自尺度爆炸而不是数据损坏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>下一 token 损失 \\(\\ell_i=- \\ell_{y_i} + \\mathrm{LSE}(\\ell)\\) 对 \\(\\ell\\) 的平移不变。优化器可以让 \\(\\|\\ell\\|_\\infty\\) 与 LSE 一起漂到 \\(10^4\\) 量级，训练损失看起来仍在降。BF16 的指数在大约 \\(88\\) 以上溢出；即便用稳定的 \\(\\mathrm{LSE}=\\mathrm{max}+\\log\\sum e^{\\ell-\\mathrm{max}}\\)，max 本身进半精度缓冲时仍可能 Inf。PaLM 把一项 \\(\\alpha z^2\\) 加进损失，明确惩罚过大的 log-partition。Gopher 同样强调大模型训练里的 logit 增长与稳定性技巧。这不是新的语言建模目标，是数值护栏。</p><p>MoE 路由器的 logits 更短、更容易两极分化。<a href="/llm/moe-router-gradient">路由器梯度</a> 在 \\(p\\approx 1\\) 时锁死；router z-loss 惩罚路由 LSE，等于把门控从饱和区拉回。Switch / ST-MoE 把这项写成稳定性组件。词表 z-loss 与 router z-loss 公式同类、作用对象不同，不要共用一个系数就以为都罩住了。</p><h3 id="平移不变性是漏洞不是特性" tabindex="-1">平移不变性是漏洞不是特性 <a class="header-anchor" href="#平移不变性是漏洞不是特性" aria-label="Permalink to &quot;平移不变性是漏洞不是特性&quot;">​</a></h3><p>从概率模型看，过参数化的 logits 有多余自由度。从浮点与门控看，这个自由度会吃掉指数的动态范围，并让「乘 \\(p\\)」的梯度消失。μP 管的是宽度变化时<strong>更新幅度</strong>；z-loss 管的是<strong>绝对 logit 尺度</strong>。两者同时需要：只 μP 不钉 \\(z\\)，宽模型仍能把输出头推到溢出；只 z-loss 不定标，窄扫到的 \\(\\eta\\) 迁不走。<span class="marginnote">z-loss 的 \\(z\\) 是 \\(\\log\\sum\\exp(\\ell)\\)，不是权重衰减里的 \\(\\|W\\|^2\\)。有人把输出头权重变大误叫成 z 爆炸。应直接记录 LSE 或 \\(\\|\\ell\\|_\\infty\\) 的滑动均值，不要用 \\(\\|W_{\\mathrm{lm}}\\|\\) 当代理——RMSNorm 之后两者可以脱钩。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="词表项与路由项怎么写" tabindex="-1">词表项与路由项怎么写 <a class="header-anchor" href="#词表项与路由项怎么写" aria-label="Permalink to &quot;词表项与路由项怎么写&quot;">​</a></h3><p>对每个位置（或对路由 logits）计算：</p> \\[z_i=\\log\\sum_{j=1}^{|V|}\\exp(\\ell_{i,j}),\\qquad L_z=\\alpha\\,\\mathbb{E}_i[z_i^2]. \\]<p>\\(\\alpha\\) 很小，PaLM 一类配方用 \\(10^{-4}\\) 量级。加在主 CE 上。实现必须用稳定 LSE，否则 z-loss 自己先 NaN。Cut CE 若在片上算 LSE，应把 \\(z_i\\) 一并回传，避免再物化整表只为算这项。</p><p>对 MoE 路由，\\(|V|\\) 换成专家数 \\(N\\)，只在路由 softmax 上加。系数可以与词表 \\(\\alpha\\) 不同：路由维更小，同样 \\(\\alpha\\) 对尺度的拉力更强。DeepSeek 式偏置均衡不替代 z-loss：偏置改的是相对负载，z-loss 改的是 logits 的公共偏移与范数。</p>',14)),(l(),p(m,null,{default:s(()=>[h(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20LGT%5B%22%E5%88%86%E7%B1%BB%E6%88%96%E8%B7%AF%E7%94%B1%20logits%22%5D%20--%3E%20CE%5B%22%E4%BA%A4%E5%8F%89%E7%86%B5%EF%BC%9A%E5%8F%AA%E7%BA%A6%E6%9D%9F%E6%A6%82%E7%8E%87%22%5D%0A%20%20LGT%20--%3E%20Z%5B%22LSE%20z%22%5D%0A%20%20Z%20--%3E%20ZL%5B%22alpha%20z%20%E5%B9%B3%E6%96%B9%22%5D%0A%20%20CE%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%22%5D%0A%20%20ZL%20--%3E%20OPT%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(L_z\\) 的梯度把所有 logits 往下拉（当 \\(z\\gt 0\\)），近似于给输出一个指向「整体变小」的公共力，而不改变（到一阶）相对差——相对差仍由 CE 管。实际耦合是：CE 想拉大正确类与错误类的间隔，间隔变大往往抬高 LSE；z-loss 反对抬高。结果是间隔靠<strong>压低错误类</strong>而不是<strong>抬高正确类</strong>来实现。这会影响后期校准：模型可能更「低估」绝对 logit，温度缩放的最优温度会变。解码温度若按未加 z-loss 的模型来抄，会偏锋利或偏平。</p><p>与梯度裁剪的关系：clip 卡的是更新步长，不卡 \\(\\ell\\) 的水平。尖峰时 clip 先触发，logits 已大的状态下每步被砍，训练变慢，但 \\(z\\) 不一定回来。z-loss 是水平拉力，clip 是速度限制，不是替代。</p><p><span class="marginnote">输出范数增长有时来自嵌入与 \\(\\gamma\\) 的共同放大。z-loss 作用在 logits，会倒逼这些增益。若同时把嵌入从衰减里豁免（AdamW 分组），两边在打架。分组课已经警告过；这里表现为 \\(L_z\\) 降不下去、CE 仍正常。</span></p><h3 id="何时-z-loss-会伤害质量" tabindex="-1">何时 z-loss 会伤害质量 <a class="header-anchor" href="#何时-z-loss-会伤害质量" aria-label="Permalink to &quot;何时 z-loss 会伤害质量&quot;">​</a></h3><p>\\(\\alpha\\) 过大，模型不敢把正确类 logit 拉到足以压过巨大词表里的竞争项，CE 平台抬高。词表越大，同样间隔需要的绝对尺度可以更大，应略调 \\(\\alpha\\) 或对 \\(z\\) 减一个目标偏置（惩罚 \\((z-z_0)^2\\)）。不要把 PaLM 的 \\(\\alpha\\) 原样贴到 256K 词表上当真理。长序列下每个位置一项，\\(L_z\\) 的 batch 均值稳定，但某几个位置的 \\(z\\) 仍可爆；应看分位数，不只看均值。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>推理通常不加 z-loss（它不是解码目标），但训练钉住的尺度会留在权重里。量化、FP8 推理对 logit 动态范围敏感：训练期 z-loss 等于给激活量化留了余量。关掉 z-loss 的长训检查点，后期再量化更易在 lm_head 爆炸。这是和压缩课的接口，本课只点到。</p><p>Router z-loss 过强会把路由推向均匀，类似加大均衡 \\(\\alpha\\)，专项化变差。应与专家负载日志一起看：负载已均且熵很高时，先降 router z-loss，而不是再加专家。词表 z-loss 不应用来当「额外正则提高下游」——它是稳定项；下游涨了算副作用，没涨也不说明实现错了。</p><p><span class="marginnote">不要编造 z-loss 的 arXiv 编号。写配方时引用 PaLM（Chowdhery 等）、Gopher（Rae 等）的稳定性叙述，以及 MoE 上 ST-MoE / Switch 的 router z-loss。系数以你复现的代码为准。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交叉熵对 logits 平移不变；z-loss 惩罚 LSE 的平方，钉住绝对尺度。</li><li>保护半精度指数、Cut CE 归约、以及 MoE 门控不饱和。</li><li>与 μP、权重衰减、梯度裁剪分工不同：尺度 / 宽度定标 / 范数 / 步长。</li><li>\\(\\alpha\\) 过大抬高 CE；词表变大时不要照抄小词表系数。</li><li>词表 z-loss 与 router z-loss 分开记、分开调。</li><li>出处：PaLM、Gopher 的大规模训练实践；Switch / ST-MoE 的路由稳定性。</li></ul>',12))])}const P=e(z,[["render",d]]);export{S as __pageData,P as default};
